#include <stdio.h>
/* binary search in a sorted array */
int _daugaunee_palatana_ha(int _irajzasha_tauna_ha[], int shameera, int keela_i) {
  int teeta = 0, lau_rda = shameera - 1;
  while (teeta <= lau_rda) {
    int manajza = teeta + (lau_rda - teeta) / 2;
    if (_irajzasha_tauna_ha[manajza] == keela_i) return manajza;
    if (_irajzasha_tauna_ha[manajza] < keela_i) teeta = manajza + 1; else lau_rda = manajza - 1;
  }
  return -1;
}
